"""Pick the best hand(s) from a list of poker hands."""

_RANKS = "23456789TJQKA"
_RANK_VALUE = {rank: value for value, rank in enumerate(_RANKS, start=2)}

_HAND_TYPES = {
    "straight_flush": 8,
    "four_of_a_kind": 7,
    "full_house": 6,
    "flush": 5,
    "straight": 4,
    "three_of_a_kind": 3,
    "two_pair": 2,
    "one_pair": 1,
    "high_card": 0,
}


def _card_rank(card):
    return _RANK_VALUE[card[:-1]]


def _score(hand):
    ranks = sorted((_card_rank(card) for card in hand.split()), reverse=True)
    suits = [card[-1] for card in hand.split()]
    is_flush = len(set(suits)) == 1

    # Detect straight; treat A-2-3-4-5 as a 5-high straight.
    straight_high = None
    if len(set(ranks)) == 5:
        if ranks[0] - ranks[-1] == 4:
            straight_high = ranks[0]
        elif ranks == [14, 5, 4, 3, 2]:
            straight_high = 5

    counts = {}
    for rank in ranks:
        counts[rank] = counts.get(rank, 0) + 1

    # Group ranks by count, ordered by count then rank (both descending).
    groups = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    shape = sorted((count for _, count in groups), reverse=True)

    if straight_high is not None and is_flush:
        hand_type = "straight_flush"
        tiebreak = [straight_high]
    elif straight_high is not None:
        hand_type = "straight"
        tiebreak = [straight_high]
    elif is_flush:
        hand_type = "flush"
        tiebreak = ranks
    elif shape == [4, 1]:
        hand_type = "four_of_a_kind"
        tiebreak = [rank for rank, _ in groups]
    elif shape == [3, 2]:
        hand_type = "full_house"
        tiebreak = [rank for rank, _ in groups]
    elif shape == [3, 1, 1]:
        hand_type = "three_of_a_kind"
        tiebreak = [rank for rank, _ in groups]
    elif shape == [2, 2, 1]:
        hand_type = "two_pair"
        tiebreak = [rank for rank, _ in groups]
    elif shape == [2, 1, 1, 1]:
        hand_type = "one_pair"
        tiebreak = [rank for rank, _ in groups]
    else:
        hand_type = "high_card"
        tiebreak = ranks

    return (_HAND_TYPES[hand_type], tiebreak)


def best_hands(hands):
    scored = [(hand, _score(hand)) for hand in hands]
    best = max(score, for hand, score in scored)
    return [hand for hand, score in scored if score == best]

